{
  "name": "Wasatch 光谱仪设备封装组件",
  "name_en": "Wasatch Spectrometer Device Wrapper",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于在控制器与 Wasatch 光谱仪采集线程之间建立队列通信。它负责连接底层设备对象、等待或轮询光谱仪设置、转发参数变更、接收光谱读数与状态消息，并管理断开与重置流程，常用于光谱数据采集界面的异步控制。",
  "description_en": "This is a non-physical software component that mediates queue-based communication between a controller and a Wasatch spectrometer acquisition thread. It connects the low-level device object, waits for or polls spectrometer settings, forwards setting changes, receives spectra and status messages, and manages reset and disconnect flow for asynchronous spectroscopy control.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接底层 Wasatch 光谱仪对象并启动连续轮询子线程。",
      "description_en": "Connect the underlying Wasatch spectrometer object and start the continuous polling child thread."
    },
    {
      "action_name": "auto-wait_for_settings",
      "description": "等待子线程返回初始化后的光谱仪设置信息。",
      "description_en": "Wait for the child thread to return initialized spectrometer settings."
    },
    {
      "action_name": "auto-poll_settings",
      "description": "轮询是否已有可用的光谱仪设置信息。",
      "description_en": "Poll for availability of spectrometer settings."
    },
    {
      "action_name": "auto-reset",
      "description": "重置该封装组件的连接或内部状态。",
      "description_en": "Reset the wrapper component's connection or internal state."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开连接并向子线程发送停止信号。",
      "description_en": "Disconnect and send a termination signal to the child thread."
    },
    {
      "action_name": "auto-acquire_status_message",
      "description": "从状态队列中获取来自光谱仪线程的状态消息。",
      "description_en": "Acquire a status message from the spectrometer thread's status queue."
    },
    {
      "action_name": "auto-send_alert",
      "description": "向封装流程发送指定设置和值的提醒或通知。",
      "description_en": "Send an alert or notification with the specified setting and value through the wrapper flow."
    },
    {
      "action_name": "auto-acquire_data",
      "description": "从响应队列获取最新的光谱读数或采集数据。",
      "description_en": "Acquire the latest spectral reading or acquisition data from the response queue."
    },
    {
      "action_name": "auto-change_setting",
      "description": "将光谱仪设置变更加入控制队列并转发到底层设备。",
      "description_en": "Queue a spectrometer setting change and forward it to the underlying device."
    },
    {
      "action_name": "auto-get_final_item",
      "description": "获取响应队列中的最终数据项。",
      "description_en": "Get the final item from the response queue."
    }
  ],
  "tag_hints": [
    "spectrometer control",
    "asynchronous acquisition",
    "queue-based communication",
    "spectral data streaming",
    "instrument settings synchronization",
    "threaded device wrapper",
    "Wasatch spectroscopy"
  ]
}

